U='https://jishuzhan.net/article/1951482261190258690'
E='第九届(2024-2025)'; ST='全国总决赛(高职组)理论·网友回忆'
NOFIG='【注意】原题含拓扑图/配置截图，原文未保存图片，本题仅可参考思路。'
R=[]
def r(id,dom,typ,stem,opts,ans,exp,tags,kp,fig=False):
    R.append(dict(id=id,source_url=U,edition=E,stage=ST,domain=dom,type=typ,stem=stem,
      options=[dict(key=k,text=t) for k,t in zip('ABCDEFG',opts)],answer=list(ans),
      explanation=(NOFIG if fig else '')+exp+'（解析摘自技术栈原文并精简）',tags=tags,credibility='回忆',kp=kp))
r('js-dt-1','数通','单选','公司C数据中心两台核心路由器Router A和Router B使用VRRP提供默认网关。A为Master，B为备份。要求A故障时B平稳接管，A故障恢复后不会立刻成为Master。以下哪一项是合理的部署方案？',['在Router B上配置一个较高的优先级，并启用抢占功能','在Router A和Router B上配置相同的优先级，并启用抢占功能','在Router A上配置较高的优先级，并禁用抢占功能','在Router A上配置较高的优先级，在Router B上配置并启用抢占功能'],'C','A是Master所以优先级更高；要求A恢复后不立即抢回，所以禁用抢占（非抢占模式）。',['VRRP','抢占'],'dt-vrrp')
r('js-dt-2','数通','单选','某运营商核心网络部署SRv6，怀疑Segment List配置错误。以下哪一项不应该出现在Segment List中？',['路径节点上的END SID','路径节点上的END.X SID','路径节点上的环回口IPv6地址','路径某段节点的Binding SID'],'C','End、End.X、Binding SID都是SID；普通环回口IPv6地址若未配置为SID则没有SID行为，不应出现。',['SRv6'],'dt-ext')
r('js-dt-3','数通','单选','路由设备上前缀列表配置：ip ip-prefix PL permit 172.16.16.0 20 greater-equal 21 less-equal 24。该前缀列表可以匹配多少条路由？',['16','24','30','32'],'C','前20位固定，掩码21~24：2+4+8+16=30。',['前缀列表','路由策略'],'dt-policy')
r('js-dt-4','数通','单选','跨域VPN采用Option A方案，CE1和CE2属于同一VPN，CE1不能ping通CE2。检查各PE和ASBR上vpn-instance配置，以下哪项是故障原因？',['ASBR1和ASBR2的VPN RD值不相同','ASBR1和ASBR2的VPN RT值不相同','ASBR2和PE2的VPN RD值不相同','ASBR2和PE2的VPN RT值不相同'],'D','RD只区分地址，与路由传递无关；Option A中ASBR间把对端当CE，传普通IPv4路由，ASBR1/2的RT不同不影响；ASBR2与PE2之间RT不匹配会导致路由无法导入。',['MPLS VPN','跨域','RD/RT'],'dt-mplsvpn',True)
r('js-dt-5','数通','多选','RTA(AS100)、RTB(AS200)、RTC(AS300)、RTD(AS400)、RTE(AS500)按图建立EBGP邻居。RTA引入1.1.1.1/32，默认RTE优选RTA-RTD-RTE路径（AS_PATH更短）。以下哪些方法可以使RTE优选从RTC接收的路由？',['RTC向RTE出口方向发布路由时调整MED属性为110','RTD向RTE出口方向发布路由时调整Local_Preference属性为110','RTE设置RTC方向发布路由的preferred-value值为110','RTD向RTE出口方向发布路由时调整AS_PATH为100 200 300 400'],'CD','MED越小越优，调大无效；Local_Pref不跨AS传递；preferred-value越大越优且最先比较；把下方路径AS_PATH拉长到4个AS后，上方100 200 300更短。',['BGP','选路'],'dt-bgp2',True)
r('js-dt-6','数通','多选','S节点部署OSPF IP FRR，S与R1之间链路故障时切换到S-N备份链路。为使S到D能用LFA算法计算备份下一跳，以下哪些开销可以作为S到N的开销？',['2','4','6','8'],'CD','按原文图中开销，LFA不等式10+5+X>15+5，得X>5，选6和8。',['OSPF','IP FRR','LFA'],'dt-ext',True)
r('js-dt-7','数通','多选','采用PIM-SM的组播配置（设备C-RP默认优先级为192），对给定组与RP的映射关系，描述正确的有哪些项？',['组地址为239.0.0.100，映射的RP为1.1.1.1','组地址为239.0.0.200，映射的RP为2.2.2.2','组地址为239.0.1.100，映射的RP为2.2.2.2','组地址为239.0.1.100，映射的RP为3.3.3.3'],'BD','需依据原图配置：239.0.0.x归ACL2000，对应LoopBack1/2，比较优先级后选2.2.2.2；239.0.1.x归ACL2001，对应LoopBack3(3.3.3.3)。',['组播','PIM-SM'],'dt-ext',True)
r('js-dt-8','数通','多选','公司A考虑采用Option B方案部署跨域VPN。以下哪些是Option B方案中ASBR需要部署的配置？',['ASBR间互联端口使能MPLS','ASBR上启用VPN instance实例','ASBR间配置子接口','ASBR上配置undo policy vpn-target'],'AD','Option B中ASBR间MP-EBGP交换VPNv4路由、标签转发，需使能MPLS；ASBR不维护VPN实例，需undo policy vpn-target关闭RT过滤；子接口和VPN实例是Option A的特征。',['MPLS VPN','跨域'],'dt-mplsvpn')
r('js-dc-1','DCN','单选','两台华为CE交换机组建M-LAG，下行接口连接同一台服务器，上行连接核心交换机。以下关于M-LAG部署的描述，错误的是哪一项？',['部署DFS Group用于M-LAG系统的两台设备通过协商报文确定设备的主备状态','部署双主检测可以通过设备管理网口或业务网络口','部署Peer-link为二层链路，用于交换协商报文、同步设备信息及传输部分流量','部署M-LAG的成员链路可以是物理链路也可以是聚合链路'],'D','M-LAG成员口必须是Eth-Trunk聚合链路。',['M-LAG'],'dc-mlag')
r('js-dc-3','DCN','多选','华为CE交换机构建VXLAN数据中心，使用EVPN作为控制平面。Spine上部署EVPN RR，但Leaf之间VXLAN隧道无法建立。以下哪项配置是可能原因？',['NVE接口下没有配置source ip-address','NVE接口下没有配置vni head-end peer-list protocol bgp','不同Leaf节点上的bridge-domain id不一样','不同Leaf节点上bridge-domain关联的vxlan vni id不一样'],'ABD','VTEP地址取自NVE source；EVPN动态建隧道需protocol bgp；BD ID本地有效不要求一致，但关联VNI必须一致。',['VXLAN','EVPN'],'dc-vxlan')
r('js-dc-4','DCN','多选','某金融机构基于华为CE交换机搭建无损网络，部署PFC。以下关于PFC的部署描述，正确的是哪些项？',['PFC通过发送PAUSE帧来暂停所有优先级队列的流量传输','PFC可以针对单个优先级队列独立触发反压，暂停该队列的流量传输','PFC的反压机制基于ECN(Explicit Congestion Notification)标记动态调整','手工配置PFC门限时，PFC队列级的反压帧触发门限值高于反压帧停止门限值'],'BD','PFC按优先级反压，不暂停全部；与ECN无关；触发门限高于停止门限。',['PFC','无损网络'],'dc-lossless')
r('js-sec-1','安全','单选','设备部署在内网与Internet之间，虚拟系统vsysa作为内网网关，通过根系统的公网接口连接Internet(公网服务器3.3.3.3)。查询会话表（vsysa→public，trust→untrust，出接口Virtual-if1）后，以下描述正确的是哪一项？',['在虚拟系统已部署安全策略，在根系统无需再部署安全策略','Virtual-if1为虚拟系统vsysa的接口，部署在trust区域','企业内网流量通过虚拟系统到根系统，然后转发到Internet','在虚拟系统配置到公网的静态路由，下一跳为根系统的Virtual-if接口地址'],'C','根系统和虚拟系统都要配安全策略；Virtual-if1在该场景中位于untrust；vsys到根系统的静态路由指定目的系统即可，无需下一跳。',['vsys','会话表'],'sec-vsys',True)
r('js-sec-2','安全','单选','某企业在华为云ECS上部署网站并通过EIP对外服务。以下关于华为云网络安全防护产品功能的描述，错误的是哪一项？',['DDoS原生基础防护仅对华为云内的公网IP提供DDoS攻击防护','云防火墙是新一代的云原生防火墙，提供云上互联网边界和VPC边界的防护，包括实时入侵检测与防御、全局统一访问控制、全流量分析可视化等','WAF作为一个反向代理存在于客户端和服务器之间，网站所有访问请求将先流转到WAF，WAF检测过滤恶意攻击流量后，将正常流量返回给源站','安全组是一个逻辑上的分组，为具有相同安全保护需求并相互信任的云服务器、云容器、云数据库等实例提供访问策略，在安全组中可以设置白名单和黑名单'],'D','原文解析：安全组为白名单机制，不支持黑名单。（华为云安全组后续是否支持拒绝规则待核实。）',['华为云','安全组','WAF'],'sec-cloud')
r('js-sec-3','安全','多选','DeviceA和DeviceB通过公网接口G0/0/1建立ISAKMP方式的IPsec隧道，预共享密钥认证。以下关于IPsec隧道配置的描述，正确的是哪些项？',['配置安全策略，放行隧道协商报文以及通过隧道传输的加密数据报文','在IPSec安全提议中配置加密算法、认证算法','在IPsec策略中引用IPsec安全提议、IKE安全提议','在接口G0/0/1上应用IPsec策略组'],'ABD','IPsec策略引用的是IPsec安全提议和IKE对等体，不是IKE安全提议，C错误。',['IPSec'],'sec-ipsec')
r('js-sec-4','安全','多选','某企业华为路由器启用URPF后，部分合法用户流量被错误丢弃。以下哪些网络调整可能解决该问题？',['将URPF模式从严格模式(Strict Mode)改为松散模式(Loose Mode)','存在缺省路由，配置URPF的allow-default-route参数','配置URPF的ACL参数允许合法用户的流量','通过路由策略调整某些路由的下一跳'],'ABCD','四种方式都能让合法流量通过URPF检查。',['URPF'],'sec-urpf')
r('js-wl-1','WLAN','单选','企业总部有两个异地分支，分支各有本地WAC。总部为确保无线可靠性，在分支与总部之间部署WAC实现跨Internet备份，应采用以下哪种备份方式？',['双链路热备份','双链路冷备份','N+1备份','CAPWAP断链逃生'],'C','断链逃生不是备份方式；场景中主备AC无HSB通道，排除热备；多主一备跨Internet场景为N+1。',['AC备份'],'wl-backup')
r('js-wl-2','WLAN','单选','某企业WLAN提供"wlan-net"，使用802.1X认证，WAC为认证点，发现无线终端无法完成802.1X认证。以下描述错误的是哪一项？',['为保证手机等无线终端设备可以顺利通过802.1X认证，只能选择EAP方式的802.1X认证','通过命令display aaa online-fail-record mac-address H-H-H查看无线终端设备上线失败原因','通过trace object mac-address H-H-H业务诊断功能，追踪无线终端设备上线认证过程','无线终端设备在802.1X认证失败的情况下，可以获取业务IP地址'],'D','802.1X认证成功后才能获取业务IP。',['802.1X','认证'],'wl-auth',True)
r('js-wl-3','WLAN','多选','AP支持上下行MU-MIMO和OFDMA，8根天线，最高8x8 MU-MIMO。假设AP同时与5个终端进行MU-MIMO传输，每个终端2根天线，以下描述正确的有哪些项？',['每个终端设备可以同时接收4个数据流','由于天线数量限制，每个终端设备只能接收2个数据流','总共有10个数据流在AP和终端之间传输','由于终端设备天线数量限制，AP无法实现最大化的MU-MIMO性能'],'BC','终端2天线→2流；原文按5×2=10计算总流数（但同一时刻AP最多8流，此题答案存在争议，待核实）。',['Wi-Fi 6','MU-MIMO'],'wl-wifi6')
r('js-wl-4','WLAN','多选','办公楼部署多个AP，员工移动时出现网络中断、速度下降、视频卡顿。可采取以下哪些动作排查该问题？',['优化AP之间的信道','调整AP的发射功率','优化提升客户端设备的无线网卡性能','修改AP的SSID和加密方式'],'ABD','原文答案ABD；D选项合理性存疑（修改SSID/加密方式一般不是漫游优化手段），待核实。',['漫游','射频优化'],'wl-roam')
